static object F_c1_op_wake_lines(object v_id) {
if (R.Bool(R.eq(v_id,"detective"))) {
return new System.Collections.Generic.List<object> {"我记得的最后一件事，是上船。","衣架上挂着一件风衣。右手袖口磨得发亮——我写字时总拿那儿蹭桌沿。是我的。","先出去，看看这是什么地方。"};
} else {
}
if (R.Bool(R.eq(v_id,"huo"))) {
return new System.Collections.Generic.List<object> {"……","手先去摸床沿。床板是榫接的，没用一颗钉子。","上船以后的事，没了。","挂钩上缠着机油布。顺时针，三圈半。我缠的。","起来。"};
} else {
}
if (R.Bool(R.eq(v_id,"shen"))) {
return new System.Collections.Generic.List<object> {"……","哎哟，这胳膊。酸得跟揉了半宿面似的。","昨儿……昨儿干啥了？就记得上了条船。","桌上那块磨刀石，中间都磨出槽了。谁这么舍得用。","先找口水喝。"};
} else {
}
return new System.Collections.Generic.List<object> {"……","墙里有一个很低的音，一直没断。","最后记得的，是船上的汽笛。","手指在被面上敲。四四拍。不知道敲了多久。","……那个音还在。"};
}
